from collections import Counter

def transform(grid):
    if not grid or not grid[0]:
        return grid

    rows = len(grid)
    cols = len(grid[0])

    counts = Counter(val for row in grid for val in row)
    bg = counts.most_common(1)[0][0]

    changed = [[False] * cols for _ in range(rows)]

    for r1 in range(rows):
        for c1 in range(cols):
            for r2 in range(r1 + 1, rows):
                for c2 in range(c1 + 1, cols):
                    C = grid[r1][c1]

                    if C == bg:
                        continue

                    is_border_valid = True
                    # Check Top and Bottom
                    for c in range(c1, c2 + 1):
                        if grid[r1][c] != C or grid[r2][c] != C:
                            is_border_valid = False
                            break
                    if not is_border_valid:
                        continue
                    # Check Left and Right
                    for r in range(r1, r2 + 1):
                        if grid[r][c1] != C or grid[r][c2] != C:
                            is_border_valid = False
                            break
                    if not is_border_valid:
                        continue

                    for r in range(r1, r2 + 1):
                        for c in range(c1, c2 + 1):
                            if r == r1 or r == r2 or c == c1 or c == c2:
                                changed[r][c] = True

    new_grid = [row[:] for row in grid]
    for r in range(rows):
        for c in range(cols):
            if changed[r][c]:
                new_grid[r][c] = 3

    return new_grid
